select coalesce(max(intent.tranche_sequence),0)+1 into sequence from public.weekly_message_intents intent
  where(case when p_request->>'audience'='MANAGER' then intent.recipient_generation_id=generation_id and intent.tranche_kind='MANAGER_MANUAL_RESEND'
   else intent.candidate_generation_id=generation_id and intent.tranche_kind='CANDIDATE_MANUAL_REMINDER' end);

select * into strict r from public.weekly_timesheet_submission_requests where id=m.submission_request_id
  and candidate_cohort_id=g.candidate_cohort_id and request_generation=g.generation_number and membership_hash=g.membership_hash
  and candidate_id=g.candidate_id and source_cycle_id=g.source_cycle_id;

select * into strict v_candidate_generation
    from public.weekly_candidate_outreach_generations
    where id=v_intent.candidate_generation_id;

select * into strict request from public.weekly_timesheet_submission_requests x
    where x.candidate_cohort_id=g.candidate_cohort_id and x.candidate_id=g.candidate_id and x.source_cycle_id=g.source_cycle_id
     and x.request_generation=g.generation_number and x.membership_hash=g.membership_hash and x.environment=c.environment and x.agency_id=c.agency_id;

select * into strict v_generation
  from public.weekly_manager_recipient_generations
  where id=p_recipient_generation_id and recipient_route_id=v_route.id and state='ACTIVE';

select * into strict v_old_generation from public.weekly_candidate_outreach_generations generation
      where generation.candidate_cohort_id=v_old_request.candidate_cohort_id and generation.request_kind='SUBMIT_TIMESHEET'
        and generation.generation_number=v_old_request.request_generation;

select * into strict v_submission from public.weekly_timesheet_submission_requests
    where id=private.weekly_contact_submission_request_for_generation_v1(v_generation.id)
      and state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED');

select * into v_generation
  from public.weekly_candidate_outreach_generations
  where id=p_request_id and candidate_id=p_candidate_id;

select * into strict v_contract from public.contracts
      where id=v_scope.contract_id and candidate_id=p_candidate_id
        and client_id=v_generation.client_id;

select * into strict v_timesheet from public.timesheets
        where timesheet_id=v_scope.submitted_timesheet_id
          and contract_id=v_scope.contract_id and week_ending_date=v_scope.week_ending;

select * into strict v_generation from public.weekly_candidate_outreach_generations
  where id=v_candidate_generation_id and candidate_id=v_candidate_id
    and request_kind=v_kind and state='ACTIVE' for update;

select coalesce(pg_catalog.max(component_no),0)+1 into v_component_no
  from public.candidate_submission_components
  where workflow_id=v_workflow.id and workflow_generation=v_next_generation;

select * into strict v_publication
    from public.weekly_source_projection_publications
    where id=p_projection_publication_id and state='CURRENT';

select * into strict v_cycle
    from public.weekly_source_cycles where id=v_generation.source_cycle_id
    for update;

select * into strict v_generation
  from public.weekly_candidate_outreach_generations
  where id=new.candidate_generation_id;

select * into v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id;

select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id;

select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id for update;

select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id for update;

select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_publication.correction_session_id for update;

select * into strict v_preparation
    from public.weekly_manager_route_preparations
    where message_intent_id=v_intent.id and state='BOUND';

select coalesce(pg_catalog.max(number),0)+1 into v_credential_generation
  from (
    select batch.credential_generation as number
    from public.weekly_manager_review_batches batch
    where batch.recipient_generation_id=v_generation.id
    union all
    select preparation.credential_generation
    from public.weekly_manager_route_preparations preparation
    where preparation.recipient_generation_id=v_generation.id
  ) generations;

select * into strict v_route
  from public.weekly_manager_recipient_routes
  where id=p_recipient_route_id for update;

select * into v_candidate_generation
      from public.weekly_candidate_outreach_generations
      where id=(select current_generation_id from public.weekly_candidate_cohorts where id=v_row.candidate_cohort_id);

select * into strict v_cohort
  from public.weekly_candidate_cohorts where id=(v_cohort_context->>'cohort_id')::uuid
  for update;

for pair in select distinct(value->>'candidate_id')::uuid candidate_id,(value->>'client_id')::uuid client_id
  from jsonb_array_elements(facts->'pairs'||p_extra_pairs)order by 1,2 loop
  perform private.weekly_contact_scope_lock_v1(source_group.agency_id,source_group.environment,pair.candidate_id,pair.client_id);
